/**
 * Message catalogs (spec §10.5, en + sk + cs + de + es). Compile-time-static and
 * static-host-friendly, the same property Paraglide JS gives, kept here as a
 * plain typed catalog so there's no runtime message loading. Keys are shared
 * across locales; `en` is the source of truth for the key set.
 *
 * `{name}` tokens are interpolated by t(); `.one/.few/.many` suffixes are plural
 * forms resolved by tp() (see i18n.svelte.ts). Nostr terms (Nostr, relay, npub,
 * nsec, bunker) are kept verbatim in every translation as they're not translated
 * in practice.
 *
 * Plural forms: sk and cs need .one/.few/.many (1 / 2-4 / 5+); en, de and es need
 * only .one/.many, so their key sets are identical to each other.
 *
 * Form of address: sk and cs use the formal vy. German uses the informal du
 * (lowercase), Spanish the informal tú, with ustedes for the plural so the
 * catalog reads naturally outside Spain. Both were chosen deliberately; changing
 * one means changing all of it, not one string.
 */
