    "nav.settings": "Einstellungen",
    "nav.back": "Zurück",
    "nav.backAria": "Zurück",
    "nav.homeAria": "Nostrautica Startseite",
    "nav.toggleTheme": "Design wechseln",

    // Start
    "home.title": "Triff die richtigen Leute",
    "home.intro":
      "Nostrautica findet anhand kurzer Intro-Videos und deiner öffentlichen Nostr-Aktivität heraus, wen du bei einem Event treffen solltest (und erklärt dir, warum).",
    "home.backup.title": "Sichere dein Konto",
    "home.backup.body":
      "Dauert 30 Sekunden. Ohne Backup bedeutet der Verlust dieses Geräts den Verlust deines Kontos.",
    "home.backup.now": "Jetzt sichern",
    "home.backup.saved": "Ich habe es schon gesichert",
    "home.yourEvents": "Deine Events",
    "home.role.organizer": "du organisierst",
    "home.role.attendee": "beigetreten",
    "home.role.visitor": "angesehen",
    // Ein Space, dem du laut Netzwerk beigetreten bist, dessen Schlüssel dieses Gerät aber
    // noch nicht erreicht hat (audit E9). Ein Zustand, keine Rolle: die Karte tritt an die
    // Stelle des Rollen-Badges, weil „viewed“ eine Lüge darüber wäre, wie du dorthin gelangt bist.
    "home.role.awaitingKey": "wartet auf seinen Schlüssel",
    "home.awaitingKey.note":
      "Du hast versucht, diesen beizutreten, aber der Schlüssel, der sie öffnet, hat dieses Gerät noch nicht erreicht. Öffne eines davon, damit es weiter versucht wird, oder durchsuche unten deinen gesamten Verlauf.",
    "home.createAnother": "Weiteres Event oder weitere Community erstellen",
    // Link einfügen (components/AddEventByLink.svelte). Der Text muss das PWA-Problem offen
    // benennen: für die Person mit dem Telefon in der Hand sieht das so aus, als wäre der
    // Link des Organisators kaputt, nicht als würden zwei Browser keine Sitzung teilen.
    "home.addByLink.title": "Event über einen Link hinzufügen",
    "home.addByLink.body":
      "Als App installiert kann Nostrautica Links, die du in deinem Browser öffnest, nicht sehen: das ist eine eigene Sitzung. Füge hier einen Einladungs- oder Event-Link ein, dann wird er mit dieser Identität geöffnet.",
    "home.addByLink.label": "Event-Link",
    "home.addByLink.placeholder": "Link einfügen, oder naddr1…",
    "home.addByLink.action": "Öffnen",
    "home.addByLink.error.notAnEvent":
      "Das ist ein Nostr-Link, aber er verweist nicht auf ein Event oder eine Community.",
    "home.addByLink.error.unrecognized":
      "Da ist kein Event-Link enthalten. Füge den vollständigen Link ein, einschließlich allem nach dem #.",
    "home.getStarted": "Loslegen",
    "home.getStarted.body": "Öffne den Einladungslink zu einem Event oder erstelle dein eigenes.",
    "home.loginOrCreate": "Anmelden oder Identität erstellen",
    "home.createEvent": "Event erstellen",
    "home.noEvents": "Hier ist noch nichts",
    "home.noEvents.body": "Öffne einen Einladungslink, um einem Event beizutreten, oder erstelle dein eigenes.",
    "home.loadingEvents": "Deine Events werden geladen…",
    "home.restoringSession": "Dein Signer wird wieder verbunden…",
    "home.scanFailed.body":
      "Die Suche nach deinen Events konnte nicht abgeschlossen werden: dein Signer hat nicht geantwortet. Es ist nichts verloren, sie sind weiterhin auf deinen Relays.",
    "home.scanIncomplete":
      "Diese Liste ist möglicherweise unvollständig: die Prüfung deiner Events wurde nicht abgeschlossen.",
    // Ehrlichkeit bei mehreren Geräten (2026-09-13). „No events yet“ musste drei
    // verschiedene Sachverhalte auf einmal ausdrücken; diese hier trennen sie.
    "home.signedOut.title": "Du bist abgemeldet",
    "home.signedOut.stale":
      "Diese Events sind das, was dieses Gerät zuletzt gesehen hat. Melde dich an, um nach neuen zu suchen.",
    "home.cantCheck.title": "Wir konnten nicht nach deinen Events suchen",
    "home.cantCheck.body":
      "Dieses Gerät kann gerade kein Relay erreichen, das ist also keine Antwort. Es ist nichts verloren: deine Events sind auf deinen Relays.",
    "home.keysWaiting":
      "Ein Event hat dir seinen Schlüssel gesendet, aber dieses Gerät kann die Relays dieses Events nicht erreichen, um ihn zu öffnen. Es wird weiter versucht. Wenn du den Einladungslink des Events hier öffnest, ist das Problem sofort behoben.",
    "home.deepScan.hint":
      "Routineprüfungen betrachten nur die letzten Tage. Fehlt ein Event, dem du auf einem anderen Gerät beigetreten bist, durchsuche deinen gesamten Verlauf.",
    "home.deepScan.action": "Meinen gesamten Verlauf durchsuchen",
