    "signin.remote.openAuth": "Bestätigungsseite öffnen",
    "signin.trouble": "Probleme bei der Anmeldung?",
    "signin.trouble.primal":
      "Der eingebaute Signer von Primal funktioniert hier nicht. Er weist die Event-Kinds, die Nostrautica veröffentlicht, stillschweigend zurück, sodass die Anmeldung zwar funktioniert zu haben scheint, danach aber nichts gespeichert wird, was du tust. Verwende Amber unter Android, Clave unter iOS oder einen anderen NIP-46-Signer.",
    "signin.trouble.wrongApp":
      "Falsche App geöffnet? Sind mehrere Signer installiert, öffnet der Button den, der sich den Link geschnappt hat, und das ist oft nicht der gewünschte. Kopiere den Code oben, öffne selbst den gewünschten Signer und füge ihn dort ein.",
    "signin.trouble.bunker":
      "Oder andersherum: Erstelle in deinem Signer eine Verbindung, kopiere den bunker://-Link, den er dir gibt, und füge ihn unten bei „Schlüssel einfügen“ ein.",
    "signin.paste": "Schlüssel einfügen",
    "signin.paste.placeholder": "nsec1… / ncryptsec1… / bunker://…",
