export type Locale = keyof typeof messages;
export type MessageKey = keyof (typeof messages)["en"];
export const LOCALES: Locale[] = ["en", "sk", "cs", "de", "es"];
export const LOCALE_NAMES: Record<Locale, string> = {
  en: "English",
  sk: "Slovenčina",
  cs: "Čeština",
  de: "Deutsch",
  es: "Español",
};
